  thorns: ThornsIcon,
  shell: ShellIcon,
  "life-stone": LifeStoneIcon,
  dice: DiceIcon,
  magnet: MagnetIcon,
  bandage: BandageIcon,
  purse: PurseIcon,
  flag: FlagIcon,
  flame: FlameIcon,
  wave: WaveIcon,
  lightning: LightningIcon,
  oak: OakIcon,
  "fish-hook": FishHookIcon,
